class Solution:
    def customSortString(self, order, s):
        counts = [0] * 26
        for ch in s:
            counts[ord(ch) - ord('a')] += 1
        out = []
        for ch in order:
            idx = ord(ch) - ord('a')
            if counts[idx]:
                out.append(ch * counts[idx])
                counts[idx] = 0
        for idx in range(26):
            if counts[idx]:
                out.append(chr(idx + ord('a')) * counts[idx])
        return ''.join(out)

